57	func loadOpenAPISpec(path string) (*openAPISpec, error) {
58		data, err := os.ReadFile(path)
59		if err != nil {
60			return nil, errors.Wrap(err, "failed to read OpenAPI spec")
61		}
62	
63		spec := &openAPISpec{}
64		if err := yaml.Unmarshal(data, spec); err != nil {
65			return nil, errors.Wrap(err, "failed to parse OpenAPI spec")
66		}
67		if spec.Paths == nil {
68			return nil, errors.New("OpenAPI spec has no paths")
69		}
70		return spec, nil
71	}
