128	func resolveSchemaRef(spec *openAPISpec, schema jsonSchema) (jsonSchema, error) {
129		defs := map[string]any{}
130		resolved, err := resolveSchemaValue(spec, schema, defs, map[string]bool{}, true)
131		if err != nil {
132			return nil, err
133		}
134	
135		resolvedSchema, ok := resolved.(map[string]any)
136		if !ok {
137			return nil, errors.New("resolved schema is not an object")
138		}
139		if len(defs) > 0 {
140			resolvedSchema["$defs"] = defs
141		}
142		return jsonSchema(resolvedSchema), nil
143	}
