201	// per-operation overrides that the HTTP method alone cannot express.
202	func annotationsForOperation(operation *openAPIOperation, title string) *sdkmcp.ToolAnnotations {
203		annotations := annotationsForMethod(operation.Method, title)
204		if idempotentOperationIDs[operation.OperationID] {
205			annotations.IdempotentHint = true
206		}
207		return annotations
